// ─── READ CONFIG + FETCH PROJECT QUEUE ──────────────────────────────────────
const fs   = require('fs');
const path = require('path');

const configPath    = '/data/wallpaper/config.json';
const stylesPath    = '/data/wallpaper/styles.json';
const socialPath    = '/data/wallpaper/social.json';
const processedPath = '/data/wallpaper/processed.json';
const localCsvPath  = '/data/wallpaper/projects.csv';

const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
const styles = JSON.parse(fs.readFileSync(stylesPath, 'utf8'));
const social = JSON.parse(fs.readFileSync(socialPath, 'utf8'));

// Check scheduled hour
const now  = new Date();
const hour = now.getHours();
if (hour !== config.batch_schedule_hour) {
  return [{ json: { skip: true, reason: `Not batch hour (${hour} vs ${config.batch_schedule_hour})` } }];
}

// Load processed log (tracks which projects have been generated)
let processed = [];
try { processed = JSON.parse(fs.readFileSync(processedPath, 'utf8')); } catch(e) { processed = []; }
const processedKeys = new Set(processed.map(p => p.key));

// Fetch CSV — Google Sheet or local file
let csvRaw;
const source = config.projects_source || 'local';
if (source === 'google_sheet' && config.google_sheet_csv_url) {
  const res = await fetch(config.google_sheet_csv_url);
  if (!res.ok) throw new Error(`Failed to fetch Google Sheet: ${res.status}`);
  csvRaw = await res.text();
} else {
  csvRaw = fs.readFileSync(localCsvPath, 'utf8');
}

// Parse CSV (handles quoted fields)
function parseCsvLine(line) {
  const result = [];
  let cur = '', inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') { inQ = !inQ; }
    else if (c === ',' && !inQ) { result.push(cur.trim()); cur = ''; }
    else { cur += c; }
  }
  result.push(cur.trim());
  return result;
}

const lines  = csvRaw.trim().split('\n');
const header = parseCsvLine(lines[0]);
const rows   = [];

for (let i = 1; i < lines.length; i++) {
  if (!lines[i].trim()) continue;
  const vals = parseCsvLine(lines[i]);
  const row  = {};
  header.forEach((k, idx) => { row[k] = (vals[idx] || '').replace(/^"|"$/g, ''); });

  // Skip empty or help rows
  const sno = row['S.No'];
  if (!sno || isNaN(Number(sno)) || !row.project_name) continue;

  // Skip if already processed or not pending
  const rowKey = `${sno}_${row.project_name}`;
  if (processedKeys.has(rowKey)) continue;
  const st = (row.status || '').toLowerCase().trim();
  if (st && st !== 'pending') continue;

  rows.push({ ...row, _rowKey: rowKey });
}

if (rows.length === 0) {
  return [{ json: { skip: true, reason: 'No pending/unprocessed rows in queue' } }];
}

const cleanStyles = {};
Object.keys(styles).forEach(k => { if (!k.startsWith('_')) cleanStyles[k] = styles[k]; });

return rows.map(row => ({
  json: {
    row,
    config,
    styles: cleanStyles,
    social,
    processedPath,
    csvPath: localCsvPath,
    header,
    source
  }
}));

// ─── OLLAMA PROMPT ENRICHMENT ───────────────────────────────────────────────
// Ollama ALWAYS runs — it fills every gap and adds creative depth.
const row    = $json.row;
const config = $json.config;
const styles = $json.styles;
const social = $json.social;

// Determine Use Case aura
const useCase = (row['Use Case'] || row.use_case || 'wallpaper').toLowerCase();
const useCaseAura = {
  wallpaper: 'seamless full-bleed background, no UI elements, immersive environment',
  poster:    'studio product photography, strong focal point, premium ad quality',
  sticker:   'isolated subject on transparent/solid background, bold clean edges, cartoon-friendly',
  frame:     'ornate decorative border, baroque or luxury frame style, elegant inner space'
};
const aura = useCaseAura[useCase] || useCaseAura.wallpaper;

// Style preset
const styleKey = row.style || 'Cinematic';
const preset   = styles[styleKey] || styles['Cinematic'];

// Build Ollama system prompt
const systemPrompt = `You are an expert AI art director for social media wallpaper packs. 
Your job is to create the perfect image generation prompt.
Always respond with ONLY a JSON object — no markdown, no explanation, nothing else.
Required JSON keys: main_prompt, negative_prompt, title, description, tags (array of 10), mood, color_palette, subject_details`;

// Build Ollama user prompt
const userPrompt = `Create an image generation prompt for this project:

Project: ${row.project_name}
Theme: ${row.theme}
Style: ${styleKey}
Use Case: ${useCase} — Aura: ${aura}
Mood: ${row.mood || 'not specified'}
Color Palette: ${row.color_palette || 'not specified'}
Subject Details: ${row.subject_details || 'not specified'}
Custom Prompt: ${row.custom_prompt || ''}
Additional: ${row.prompt_add || ''}
Negative Prompt Override: ${row.negative_prompt || ''}

Style base prefix: ${preset.prompt_prefix}
Style base suffix: ${preset.prompt_suffix}

Rules:
1. Combine the style base with the theme creatively — do not copy verbatim
2. The image is 9:16 vertical (1080×1920) — compose accordingly
3. Use Case "${useCase}" requires: ${aura}
4. Fill ALL gaps using your creative expertise even if fields are empty
5. Make the prompt specific, vivid and optimised for SDXL/RealVisXL
6. Title should be 3-5 words, punchy, suitable for Instagram
7. Description should be 1-2 sentences for the Instagram caption
8. Tags should include #momentlabs and 9 relevant hashtags`;

// Call Ollama
const ollamaUrl = config.ollama_url || 'http://host.docker.internal:11434';
const model     = config.ollama_model || 'qwen3:8b';

const response = await fetch(`${ollamaUrl}/api/chat`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    model,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user',   content: userPrompt }
    ],
    stream: false,
    options: { temperature: 0.8, num_predict: 800 }
  })
});

if (!response.ok) throw new Error(`Ollama error: ${response.status}`);
const data = await response.json();
let enriched;
try {
  const raw = data.message?.content || data.response || '{}';
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  enriched = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
} catch (e) {
  // Fallback if Ollama returns something unparseable
  enriched = {
    main_prompt:     `${preset.prompt_prefix}, ${row.theme}, ${preset.prompt_suffix}`,
    negative_prompt: row.negative_prompt || preset.negative_prompt,
    title:           row.project_name,
    description:     `${row.project_name} — premium wallpaper by Moment.Labs`,
    tags:            ['#momentlabs', '#wallpaper', '#premium', '#aesthetic'],
    mood:            row.mood || 'cinematic',
    color_palette:   row.color_palette || 'vivid',
    subject_details: row.subject_details || row.theme
  };
}

// Add watermark text to negative if sticker (we want clean edges)
if (useCase === 'sticker') {
  enriched.negative_prompt = (enriched.negative_prompt || '') + ', background, shadow, watermark';
}

const count  = parseInt(row.count) || parseInt($json.config.default_count) || 4;
const model_ = row.model  || config.default_model || 'realvis';
const steps_ = parseInt(row.steps) || preset.steps || config.default_steps || 25;
const cfg_   = parseFloat(row.cfg_scale) || preset.cfg   || config.default_cfg   || 7.5;

return [{
  json: {
    ...$json,
    enriched,
    useCase,
    count,
    model: model_,
    steps: steps_,
    cfg:   cfg_,
    preset
  }
}];

// ─── COMFYUI WORKFLOW BUILDER ────────────────────────────────────────────────
// Builds a ComfyUI API-format workflow and submits it.
const config   = $json.config;
const enriched = $json.enriched;
const row      = $json.row;

const models = config.models || {};
const modelFile = models[$json.model] || models['realvis'] || 'realvisxlV50_v50Bakedvae.safetensors';

const width  = config.image?.width  || 1080;
const height = config.image?.height || 1920;
const count  = $json.count || 4;
const steps  = $json.steps || 25;
const cfg    = $json.cfg   || 7.5;

// Build minimal ComfyUI API workflow (SDXL compatible)
const workflow = {
  "1": {
    "class_type": "CheckpointLoaderSimple",
    "inputs": { "ckpt_name": modelFile }
  },
  "2": {
    "class_type": "CLIPTextEncode",
    "inputs": {
      "text": enriched.main_prompt,
      "clip": ["1", 1]
    }
  },
  "3": {
    "class_type": "CLIPTextEncode",
    "inputs": {
      "text": enriched.negative_prompt || 'watermark, text, blur, ugly, deformed',
      "clip": ["1", 1]
    }
  },
  "4": {
    "class_type": "EmptyLatentImage",
    "inputs": { "width": width, "height": height, "batch_size": count }
  },
  "5": {
    "class_type": "KSampler",
    "inputs": {
      "model": ["1", 0],
      "positive": ["2", 0],
      "negative": ["3", 0],
      "latent_image": ["4", 0],
      "seed": Math.floor(Math.random() * 9999999999),
      "steps": steps,
      "cfg": cfg,
      "sampler_name": $json.preset?.sampler || "euler_ancestral",
      "scheduler": "karras",
      "denoise": 1.0
    }
  },
  "6": {
    "class_type": "VAEDecode",
    "inputs": {
      "samples": ["5", 0],
      "vae": ["1", 2]
    }
  },
  "7": {
    "class_type": "SaveImage",
    "inputs": {
      "images": ["6", 0],
      "filename_prefix": `momentlabs_${row.project_name.replace(/\s+/g, '_').toLowerCase()}`
    }
  }
};

// Submit to ComfyUI
const comfyUrl = config.comfyui_url || 'http://host.docker.internal:8188';
const submitResponse = await fetch(`${comfyUrl}/prompt`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ prompt: workflow, client_id: 'moment_labs_n8n' })
});

if (!submitResponse.ok) {
  throw new Error(`ComfyUI submit failed: ${submitResponse.status} ${await submitResponse.text()}`);
}

const submitData = await submitResponse.json();
const promptId   = submitData.prompt_id;

if (!promptId) throw new Error('ComfyUI did not return a prompt_id');

return [{ json: { ...$json, promptId, comfyUrl, width, height, count } }];

