const https = require('http');
const url   = '{{ $json.comfyUrl }}/history/{{ $json.promptId }}';
const max   = {{ $json.config.poll_max_attempts || 36 }};
const wait  = {{ $json.config.poll_interval_sec || 5 }} * 1000;

function poll(attempt) {
  if (attempt > max) { console.log(JSON.stringify({done:false,error:'timeout'})); return; }
  https.get(url, res => {
    let d='';
    res.on('data',c=>d+=c);
    res.on('end',()=>{
      try {
        const h = JSON.parse(d);
        const e = h['{{ $json.promptId }}'];
        if (e && e.status && e.status.completed) {
          const outputs = e.outputs;
          const images  = [];
          Object.values(outputs).forEach(o => { if(o.images) o.images.forEach(img => images.push(img)); });
          console.log(JSON.stringify({done:true, images}));
        } else {
          setTimeout(() => poll(attempt+1), wait);
        }
      } catch(err) { setTimeout(()=>poll(attempt+1), wait); }
    });
  }).on('error', () => setTimeout(()=>poll(attempt+1), wait));
}
poll(1);
"

