// ─── DOWNLOAD & SAVE IMAGES + META ──────────────────────────────────────────
const fs     = require('fs');
const path   = require('path');
const https  = require('http');

const stdout = $json.stdout || '{}';
let pollResult;
try { pollResult = JSON.parse(stdout.trim().split('\n').pop()); }
catch(e) { throw new Error('Could not parse ComfyUI poll result: ' + stdout); }

if (!pollResult.done) throw new Error(`ComfyUI timed out or errored: ${JSON.stringify(pollResult)}`);

const row      = $json.row;
const enriched = $json.enriched;
const config   = $json.config;
const social   = $json.social;
const images   = pollResult.images || [];

// Project output folder
const safeProject = row.project_name.replace(/[^a-zA-Z0-9_\-]/g, '_');
const ts          = new Date().toISOString().split('T')[0];
const outFolder   = path.join(config.output_folder, `${ts}_${safeProject}`);
if (!fs.existsSync(outFolder)) fs.mkdirSync(outFolder, { recursive: true });

// Download each image
const comfyBase = config.comfyui_url || 'http://host.docker.internal:8188';
const savedFiles = [];

for (let i = 0; i < images.length; i++) {
  const img      = images[i];
  const filename = `${safeProject}_${String(i+1).padStart(2,'0')}.png`;
  const outPath  = path.join(outFolder, filename);
  const dlUrl    = `${comfyBase}/view?filename=${img.filename}&type=${img.type}&subfolder=${img.subfolder || ''}`;

  // Fetch and save
  await new Promise((resolve, reject) => {
    const file = fs.createWriteStream(outPath);
    https.get(dlUrl, resp => {
      resp.pipe(file);
      file.on('finish', () => { file.close(); resolve(); });
    }).on('error', err => { fs.unlinkSync(outPath); reject(err); });
  });

  savedFiles.push({ filename, path: outPath, comfyFilename: img.filename });
}

// Write meta.json
const meta = {
  project_name:  row.project_name,
  use_case:      $json.useCase,
  style:         row.style,
  date:          new Date().toISOString(),
  title:         enriched.title,
  description:   enriched.description,
  tags:          enriched.tags,
  mood:          enriched.mood,
  color_palette: enriched.color_palette,
  subject_details: enriched.subject_details,
  main_prompt:   enriched.main_prompt,
  negative_prompt: enriched.negative_prompt,
  model:         $json.model,
  steps:         $json.steps,
  cfg:           $json.cfg,
  image_count:   savedFiles.length,
  images:        savedFiles.map(f => f.filename),
  instagram:     social.instagram_handle,
  recycle_after: row.recycle_after_days || config.recycle_after_days || 30
};
fs.writeFileSync(path.join(outFolder, 'meta.json'), JSON.stringify(meta, null, 2));

// Mark as processed in processed.json
const processedPath = $json.processedPath || '/data/wallpaper/processed.json';
let processed = [];
try { processed = JSON.parse(fs.readFileSync(processedPath, 'utf8')); } catch(e) { processed = []; }
processed.push({
  key:     row._rowKey || `${row['S.No']}_${row.project_name}`,
  name:    row.project_name,
  date:    new Date().toISOString(),
  folder:  outFolder,
  images:  savedFiles.length
});
fs.writeFileSync(processedPath, JSON.stringify(processed, null, 2));

return [{ json: { ...$json, outFolder, savedFiles, meta } }];

// ─── TELEGRAM NOTIFICATION ──────────────────────────────────────────────────
const fs   = require('fs');
const row  = $json.row;
const meta = $json.meta;
const social = $json.social;

if (!social.telegram_notify) {
  return [{ json: { ...$json, telegramSkipped: true } }];
}

// Read Telegram config
let notifConfig;
try {
  notifConfig = JSON.parse(fs.readFileSync('/data/notifications/config.json', 'utf8'));
} catch(e) {
  return [{ json: { ...$json, telegramSkipped: true, reason: 'notifications/config.json not found' } }];
}

const token  = notifConfig.telegram_bot_token;
const chatId = notifConfig.telegram_chat_id;
if (!token || !chatId || token === 'YOUR_BOT_TOKEN') {
  return [{ json: { ...$json, telegramSkipped: true, reason: 'Telegram not configured' } }];
}

const tagsStr = (meta.tags || []).slice(0, 5).join(' ');
const message = `✅ *Moment.Labs — Batch Done*\n\n` +
  `📦 *${meta.project_name}*\n` +
  `🎨 Style: ${row.style}  |  Use Case: ${meta.use_case}\n` +
  `🖼 Images generated: ${meta.image_count}\n` +
  `📝 *${meta.title}*\n` +
  `${meta.description}\n\n` +
  `${tagsStr}\n\n` +
  `📁 Saved to: ${$json.outFolder}`;

const telegramUrl = `https://api.telegram.org/bot${token}/sendMessage`;
const tgResponse  = await fetch(telegramUrl, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ chat_id: chatId, text: message, parse_mode: 'Markdown' })
});

return [{ json: { ...$json, telegramSent: tgResponse.ok } }];

// ─── LOG TO JOB LOGGER ───────────────────────────────────────────────────────
const row  = $json.row;
const meta = $json.meta;

// POST to the central job logger
try {
  await fetch('http://localhost:5679/webhook/automate-job-log', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      workflow: 'Moment.Labs Batch',
      status:   'success',
      details:  `${row.project_name} — ${meta.image_count} images — ${meta.use_case}`
    })
  });
} catch(e) { /* job logger offline — non-fatal */ }

return [{ json: { success: true, project: row.project_name, images: meta.image_count, folder: $json.outFolder } }];
